"use client";

import { useEffect, useId } from "react";

type BodyStyles = Pick<
  CSSStyleDeclaration,
  | "boxSizing"
  | "height"
  | "left"
  | "overflow"
  | "paddingRight"
  | "position"
  | "right"
  | "top"
  | "width"
>;

const listenerOptions = { passive: false } as const;

type ScrollLock = {
  preventTouchMove: boolean;
  touchScrollTarget: HTMLElement | null;
};

class BodyScrollLock {
  private acquiredBy = new Map<string, ScrollLock>();
  private initialBodyStyles: BodyStyles | null = null;
  private initialScrollbarSize: { priority: string; value: string } | null = null;
  private listeningForTouchMove = false;
  private scroll = { x: 0, y: 0 };

  private preventTouchMove = (event: TouchEvent) => {
    const target = event.target;
    if (
      target instanceof Node &&
      [...this.acquiredBy.values()].some(
        ({ preventTouchMove, touchScrollTarget }) =>
          preventTouchMove && touchScrollTarget?.contains(target),
      )
    ) {
      return;
    }
    event.preventDefault();
  };

  private syncTouchMoveListener() {
    const shouldListen = [...this.acquiredBy.values()].some(
      ({ preventTouchMove }) => preventTouchMove,
    );
    if (shouldListen === this.listeningForTouchMove) return;
    this.listeningForTouchMove = shouldListen;
    if (shouldListen) {
      document.body.addEventListener("touchmove", this.preventTouchMove, listenerOptions);
    } else {
      document.body.removeEventListener("touchmove", this.preventTouchMove, false);
    }
  }

  acquire(id: string, touchScrollTarget: HTMLElement | null = null, preventTouchMove = false) {
    if (this.acquiredBy.has(id)) return;
    if (this.acquiredBy.size === 0) {
      this.scroll = { x: window.scrollX, y: window.scrollY };
      this.initialBodyStyles = {
        boxSizing: document.body.style.boxSizing,
        height: document.body.style.height,
        left: document.body.style.left,
        overflow: document.body.style.overflow,
        paddingRight: document.body.style.paddingRight,
        position: document.body.style.position,
        right: document.body.style.right,
        top: document.body.style.top,
        width: document.body.style.width,
      };
      this.initialScrollbarSize = {
        priority: document.documentElement.style.getPropertyPriority("--scrollbar-size"),
        value: document.documentElement.style.getPropertyValue("--scrollbar-size"),
      };
      const scrollbarWidth = window.innerWidth - document.body.clientWidth;
      const paddingRight = Number.parseFloat(getComputedStyle(document.body).paddingRight) || 0;
      Object.assign(document.body.style, {
        boxSizing: "border-box",
        height: "100%",
        left: "0",
        overflow: "hidden",
        paddingRight: `${paddingRight + scrollbarWidth}px`,
        position: "fixed",
        right: "0",
        top: `-${this.scroll.y}px`,
        width: "100%",
      });
      document.documentElement.style.setProperty("--scrollbar-size", `${scrollbarWidth}px`);
    }
    this.acquiredBy.set(id, { preventTouchMove, touchScrollTarget });
    this.syncTouchMoveListener();
  }

  updateTouchScrollTarget(id: string, touchScrollTarget: HTMLElement | null) {
    const lock = this.acquiredBy.get(id);
    if (lock) this.acquiredBy.set(id, { ...lock, touchScrollTarget });
  }

  release(id: string) {
    if (!this.acquiredBy.delete(id)) return;
    this.syncTouchMoveListener();
    if (this.acquiredBy.size > 0 || !this.initialBodyStyles || !this.initialScrollbarSize) return;
    Object.assign(document.body.style, this.initialBodyStyles);
    if (this.initialScrollbarSize.value)
      document.documentElement.style.setProperty(
        "--scrollbar-size",
        this.initialScrollbarSize.value,
        this.initialScrollbarSize.priority,
      );
    else document.documentElement.style.removeProperty("--scrollbar-size");
    const scroll = this.scroll;
    requestAnimationFrame(() => {
      if (this.acquiredBy.size === 0) window.scrollTo(scroll.x, scroll.y);
    });
    this.initialBodyStyles = null;
    this.initialScrollbarSize = null;
  }
}

export const bodyScrollLock = new BodyScrollLock();

/** Acquires the shared document-body lock while `active` is true. */
export function useBodyScrollLock(
  active: boolean,
  touchScrollTarget: HTMLElement | null = null,
  preventTouchMove = false,
) {
  const id = useId();
  useEffect(() => {
    if (!active) return;
    bodyScrollLock.acquire(id, null, preventTouchMove);
    return () => bodyScrollLock.release(id);
  }, [active, id, preventTouchMove]);
  useEffect(() => {
    if (active) bodyScrollLock.updateTouchScrollTarget(id, touchScrollTarget);
  }, [active, id, touchScrollTarget]);
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";

export const MIN_WIDTH_PERCENT = 20;
export const MAX_WIDTH_PERCENT = 85;
export const DEFAULT_WIDTH_PERCENT = 50;

const SMALL_SCREEN_QUERY = "(max-width: 800px)";

type WidthChannel = {
  subscribers: Set<() => void>;
  value?: number;
};

const widthChannels = new Map<string, WidthChannel>();

function getDrawerWidthKey(drawerKey: string) {
  return `drawer-width:${drawerKey}`;
}

function clampWidth(value: number) {
  return Math.min(MAX_WIDTH_PERCENT, Math.max(MIN_WIDTH_PERCENT, value));
}

function parseSavedWidth(value: string | null) {
  if (value === null) return undefined;
  try {
    const parsedValue: unknown = JSON.parse(value);
    return typeof parsedValue === "number" && Number.isFinite(parsedValue)
      ? clampWidth(parsedValue)
      : undefined;
  } catch {
    return undefined;
  }
}

function readSavedWidth(drawerKey: string | undefined) {
  if (!drawerKey) return undefined;
  try {
    return parseSavedWidth(window.localStorage.getItem(getDrawerWidthKey(drawerKey)));
  } catch {
    return undefined;
  }
}

function subscribeToWidth(drawerKey: string, subscriber: () => void) {
  const channel = widthChannels.get(drawerKey) ?? {
    subscribers: new Set(),
  };
  channel.subscribers.add(subscriber);
  widthChannels.set(drawerKey, channel);

  return () => {
    channel.subscribers.delete(subscriber);
    if (channel.subscribers.size === 0) widthChannels.delete(drawerKey);
  };
}

function getSyncedWidth(drawerKey: string | undefined) {
  return drawerKey ? widthChannels.get(drawerKey)?.value : undefined;
}

function persistWidth(drawerKey: string, value: number) {
  try {
    window.localStorage.setItem(getDrawerWidthKey(drawerKey), String(value));
  } catch {}

  const channel = widthChannels.get(drawerKey) ?? {
    subscribers: new Set(),
  };
  channel.value = value;
  widthChannels.set(drawerKey, channel);
  for (const subscriber of channel.subscribers) {
    subscriber();
  }
}

function getServerWidth() {
  return undefined;
}

function widthToPercent(drawerWidth: string | undefined) {
  if (!drawerWidth) return undefined;
  const normalizedWidth = drawerWidth.trim();
  const value = Number.parseFloat(normalizedWidth);
  if (!Number.isFinite(value)) return undefined;
  if (normalizedWidth.endsWith("%")) return clampWidth(value);
  if (window.innerWidth <= 0) return undefined;
  return clampWidth((value / window.innerWidth) * 100);
}

function getInitialWidth(drawerKey?: string, drawerWidth?: string) {
  return readSavedWidth(drawerKey) ?? widthToPercent(drawerWidth) ?? DEFAULT_WIDTH_PERCENT;
}

function isValidFixedWidth(drawerWidth: string) {
  const normalizedWidth = drawerWidth.trim();
  if (!normalizedWidth) return false;
  if (typeof CSS !== "undefined" && typeof CSS.supports === "function") {
    return CSS.supports("width", normalizedWidth);
  }
  return /^-?(?:\d+|\d*\.\d+)(?:%|px|rem|em|vw|vh|vmin|vmax)$/.test(normalizedWidth);
}

function isSmallScreen() {
  return typeof window !== "undefined" && typeof window.matchMedia === "function"
    ? window.matchMedia(SMALL_SCREEN_QUERY).matches
    : typeof window !== "undefined" && window.innerWidth <= 800;
}

function useSmallScreen() {
  const [smallScreen, setSmallScreen] = useState(isSmallScreen);

  useEffect(() => {
    const update = () => setSmallScreen(isSmallScreen());
    const media = window.matchMedia?.(SMALL_SCREEN_QUERY);
    media?.addEventListener?.("change", update);
    window.addEventListener("resize", update);
    update();
    return () => {
      media?.removeEventListener?.("change", update);
      window.removeEventListener("resize", update);
    };
  }, []);

  return smallScreen;
}

type DrawerResizingOptions = {
  drawerKey?: string;
  drawerMaxWidth?: string;
  drawerWidth?: string;
  enabled?: boolean;
};

export function useDrawerResizing({
  drawerKey,
  drawerMaxWidth,
  drawerWidth,
  enabled = true,
}: DrawerResizingOptions) {
  const panelRef = useRef<HTMLDivElement>(null);
  const resizeHandleRef = useRef<HTMLDivElement>(null);
  const animationFrameRef = useRef<number | null>(null);
  const stopDraggingRef = useRef<() => void>(() => undefined);
  const pendingWidthRef = useRef<number | null>(null);
  const widthIdentity = `${drawerKey ?? ""}\u0000${drawerMaxWidth ?? ""}\u0000${drawerWidth ?? ""}`;
  const subscribeWidth = useCallback(
    (subscriber: () => void) =>
      drawerKey ? subscribeToWidth(drawerKey, subscriber) : () => undefined,
    [drawerKey],
  );
  const getWidthSnapshot = useCallback(() => getSyncedWidth(drawerKey), [drawerKey]);
  const syncedWidth = useSyncExternalStore(subscribeWidth, getWidthSnapshot, getServerWidth);
  const persistedWidthPercent =
    syncedWidth ??
    (typeof window === "undefined"
      ? DEFAULT_WIDTH_PERCENT
      : getInitialWidth(drawerKey, drawerWidth));
  const smallScreen = useSmallScreen();
  const canResize = Boolean(enabled && drawerKey && !smallScreen);

  useLayoutEffect(() => {
    const panel = panelRef.current;
    if (!panel) return;

    if (smallScreen) {
      panel.style.setProperty("--drawer-width", "100%");
      panel.style.setProperty("--drawer-min-width", "100%");
      panel.style.setProperty("--drawer-max-width", "100%");
      return;
    }

    if (!enabled && drawerWidth && isValidFixedWidth(drawerWidth)) {
      panel.style.setProperty("--drawer-width", drawerWidth);
      panel.style.setProperty("--drawer-min-width", drawerWidth);
      panel.style.setProperty("--drawer-max-width", drawerWidth);
      return;
    }

    panel.style.setProperty("--drawer-width", `${persistedWidthPercent}%`);
    panel.style.setProperty("--drawer-min-width", `${MIN_WIDTH_PERCENT}%`);
    panel.style.setProperty(
      "--drawer-max-width",
      drawerMaxWidth ? `min(${MAX_WIDTH_PERCENT}%, ${drawerMaxWidth})` : `${MAX_WIDTH_PERCENT}%`,
    );
  }, [drawerMaxWidth, drawerWidth, enabled, persistedWidthPercent, smallScreen]);

  const handleResizeStart = useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      if (!canResize) return;
      event.preventDefault();

      const panel = panelRef.current;
      const handle = resizeHandleRef.current;
      if (!panel || !handle) return;

      stopDraggingRef.current();
      panel.dataset.resizing = "";
      handle.dataset.resizing = "";
      pendingWidthRef.current = persistedWidthPercent;
      const viewportWidth = window.innerWidth;

      const applyPendingWidth = () => {
        animationFrameRef.current = null;
        if (pendingWidthRef.current === null) return;
        const nextWidth = pendingWidthRef.current;
        panel.style.setProperty("--drawer-width", `${nextWidth}%`);
        handle.dataset.atMinWidth = String(nextWidth <= MIN_WIDTH_PERCENT);
        handle.dataset.atMaxWidth = String(Math.abs(nextWidth - MAX_WIDTH_PERCENT) < 1);
      };

      const handleMouseMove = (moveEvent: MouseEvent) => {
        moveEvent.preventDefault();
        pendingWidthRef.current = ((viewportWidth - moveEvent.clientX) / viewportWidth) * 100;
        if (animationFrameRef.current !== null) {
          window.cancelAnimationFrame(animationFrameRef.current);
        }
        animationFrameRef.current = window.requestAnimationFrame(applyPendingWidth);
      };

      const clearDragState = () => {
        if (animationFrameRef.current !== null) {
          window.cancelAnimationFrame(animationFrameRef.current);
          animationFrameRef.current = null;
        }
        delete panel.dataset.resizing;
        delete handle.dataset.resizing;
        document.removeEventListener("mousemove", handleMouseMove);
        document.removeEventListener("mouseup", finishDragging);
        stopDraggingRef.current = () => undefined;
      };

      const finishDragging = () => {
        if (animationFrameRef.current !== null) {
          window.cancelAnimationFrame(animationFrameRef.current);
          animationFrameRef.current = null;
          applyPendingWidth();
        }

        const nextWidth = clampWidth(pendingWidthRef.current ?? persistedWidthPercent);
        pendingWidthRef.current = null;
        panel.style.setProperty("--drawer-width", `${nextWidth}%`);
        try {
          if (drawerKey) persistWidth(drawerKey, nextWidth);
        } finally {
          clearDragState();
        }
      };

      stopDraggingRef.current = () => {
        pendingWidthRef.current = null;
        clearDragState();
      };
      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", finishDragging);
    },
    [canResize, drawerKey, persistedWidthPercent],
  );

  useLayoutEffect(
    () => () => {
      stopDraggingRef.current();
      if (animationFrameRef.current !== null) {
        window.cancelAnimationFrame(animationFrameRef.current);
      }
    },
    [canResize, widthIdentity],
  );

  return {
    panelRef,
    resizeHandleRef,
    handleResizeStart,
    persistedWidthPercent,
    enabled: canResize,
  };
}

"use client";

import { AnimatePresence } from "framer-motion";
import type { Location } from "history";
import {
  Component,
  createContext,
  Fragment,
  useCallback,
  useContext,
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type HTMLAttributes,
  type ReactNode,
  type Ref,
} from "react";

import { t } from "../../lib/scraps-locale";
import { cn } from "../../lib/utils";
import { Backdrop } from "./backdrop";
import { bodyScrollLock } from "./body-scroll-lock";
import { Button } from "./button";
import { MAX_WIDTH_PERCENT, MIN_WIDTH_PERCENT, useDrawerResizing } from "./drawer-resizing";
import { useHotkeys } from "./hotkey";
import { SlideOverPanel } from "./slide-over-panel";
import { TooltipContext } from "./tooltip";

export interface DrawerOptions {
  ariaLabel: string;
  drawerKey?: string;
  drawerMaxWidth?: string;
  drawerWidth?: string;
  mode?: "blocking" | "passive";
  onClose?: () => void;
  onOpen?: () => void;
  resizable?: boolean;
  shouldCloseOnInteractOutside?: (interactedElement: Element) => boolean;
  shouldCloseOnLocationChange?: (nextLocation: Location) => boolean;
}

type DrawerRenderProps = {
  closeDrawer: () => void;
};

type DrawerRenderer = (renderProps: DrawerRenderProps) => ReactNode;

export interface DrawerConfig {
  options: DrawerOptions;
  renderer: DrawerRenderer | null;
}

type StoredDrawerConfig = DrawerConfig & {
  callerId: string;
  revision: number;
};

type DrawerContextValue = {
  activeDrawerId: string | null;
  closeDrawer: () => void;
  openDrawer: (
    renderer: DrawerConfig["renderer"],
    options: DrawerOptions,
    callerId: string,
  ) => void;
  panelRef: React.RefObject<HTMLDivElement | null>;
};

const DrawerContext = createContext<DrawerContextValue>({
  activeDrawerId: null,
  closeDrawer: () => undefined,
  openDrawer: () => undefined,
  panelRef: { current: null },
});

const DrawerContentContext = createContext<Pick<DrawerOptions, "ariaLabel" | "onClose">>({
  ariaLabel: "slide out drawer",
  onClose: () => undefined,
});

function shouldCloseOnInteractOutsideByDefault(element: Element) {
  if (document.getElementById("modal-portal")?.contains(element)) {
    return false;
  }

  const overlay = element.closest("[data-overlay]");
  return !overlay || overlay.hasAttribute("data-drawer-backdrop");
}

function CloseIcon() {
  return (
    <svg aria-hidden="true" fill="currentColor" height="16" viewBox="0 0 16 16" width="16">
      <path d="M12.72 2.22C13.01 1.93 13.49 1.93 13.78 2.22C14.07 2.51 14.07 2.99 13.78 3.28L9.06 8L13.78 12.72C14.07 13.01 14.07 13.49 13.78 13.78C13.49 14.07 13.01 14.07 12.72 13.78L8 9.06L3.28 13.78C2.99 14.07 2.51 14.07 2.22 13.78C1.93 13.49 1.93 13.01 2.22 12.72L6.94 8L2.22 3.28C1.93 2.99 1.93 2.51 2.22 2.22C2.51 1.93 2.99 1.93 3.28 2.22L8 6.94L12.72 2.22Z" />
    </svg>
  );
}

type DrawerPanelProps = Pick<
  DrawerOptions,
  "ariaLabel" | "drawerKey" | "drawerMaxWidth" | "drawerWidth" | "onClose" | "resizable"
> & {
  children: ReactNode;
  mode: NonNullable<DrawerOptions["mode"]>;
  panelForwardRef: Ref<HTMLDivElement>;
};

function assignPanelRef(node: HTMLDivElement | null, panelForwardRef: Ref<HTMLDivElement>) {
  if (typeof panelForwardRef === "function") {
    panelForwardRef(node);
  } else if (panelForwardRef) {
    panelForwardRef.current = node;
  }
}

function DrawerPanel({
  children,
  ariaLabel,
  onClose,
  mode,
  drawerKey,
  drawerMaxWidth,
  drawerWidth,
  resizable = true,
  panelForwardRef,
}: DrawerPanelProps) {
  const { enabled, handleResizeStart, panelRef, persistedWidthPercent, resizeHandleRef } =
    useDrawerResizing({
      drawerKey,
      drawerMaxWidth,
      drawerWidth,
      enabled: resizable,
    });
  const [tooltipContainer, setTooltipContainer] = useState<HTMLDivElement | null>(null);

  return (
    <div className="pointer-events-none fixed inset-0 z-[9999] max-[800px]:pointer-events-auto max-[800px]:overflow-x-auto">
      <SlideOverPanel
        ariaLabel={ariaLabel}
        className="relative h-full! [width:clamp(var(--drawer-min-width),var(--drawer-width),var(--drawer-max-width))]! border-l border-[var(--scraps-theme-border-primary)] bg-[var(--scraps-slide-over-background)] [box-shadow:20px_0_0_var(--scraps-slide-over-background),var(--scraps-theme-shadow-high)] [--drawer-max-width:85%] [--drawer-min-width:20%] [--drawer-width:50%] data-[resizing]:[scrollbar-width:none] data-[resizing]:overflow-hidden! max-[800px]:inset-0! max-[800px]:h-full! max-[800px]:w-full! max-[800px]:max-w-full! max-[800px]:min-w-full! max-[800px]:overscroll-x-auto max-[800px]:border-0 max-[800px]:shadow-none data-[resizing]:[&_*]:[scrollbar-width:none] data-[resizing]:[&_*::-webkit-scrollbar]:hidden data-[resizing]:[&::-webkit-scrollbar]:hidden"
        mode={mode}
        panelWidth="var(--drawer-width)"
        position="right"
        ref={(node) => {
          panelRef.current = node;
          setTooltipContainer(node);
          assignPanelRef(node, panelForwardRef);
        }}
      >
        {enabled ? (
          <div
            aria-label="Resize drawer"
            className="absolute top-0 bottom-0 -left-0.5 z-[10001] w-2 cursor-ew-resize after:absolute after:top-0 after:bottom-0 after:left-0.5 after:w-1 after:bg-transparent after:opacity-80 after:transition-colors after:duration-100 after:ease-[ease] hover:after:bg-[var(--scraps-theme-blue400)] data-[at-max-width=true]:cursor-e-resize data-[at-min-width=true]:cursor-w-resize data-[resizing]:after:bg-[var(--scraps-theme-blue400)]"
            data-at-max-width={String(Math.abs(persistedWidthPercent - MAX_WIDTH_PERCENT) < 1)}
            data-at-min-width={String(persistedWidthPercent <= MIN_WIDTH_PERCENT)}
            data-slot="drawer-resize-handle"
            onMouseDown={handleResizeStart}
            ref={resizeHandleRef}
          />
        ) : null}
        <TooltipContext.Provider value={{ container: tooltipContainer }}>
          <DrawerContentContext.Provider value={{ ariaLabel, onClose }}>
            {children}
          </DrawerContentContext.Provider>
        </TooltipContext.Provider>
      </SlideOverPanel>
    </div>
  );
}

type DrawerHeaderProps = {
  children?: ReactNode;
  className?: string;
  hideBar?: boolean;
  hideCloseButton?: boolean;
  hideCloseButtonText?: boolean;
  ref?: Ref<HTMLHeadingElement>;
};

export function DrawerHeader({
  children = null,
  className,
  hideBar = false,
  hideCloseButton = false,
  hideCloseButtonText = false,
  ref,
}: DrawerHeaderProps) {
  const { onClose } = useDrawerContentContext();

  return (
    <header
      className={cn(
        "sticky top-0 z-[10000] flex h-[53px] shrink-0 items-center justify-start border-b border-[var(--scraps-theme-border-primary)] bg-background px-3 py-1.5",
        hideBar && "gap-2",
        hideCloseButton && "py-3",
        className,
      )}
      ref={ref}
    >
      {!hideCloseButton ? (
        <Fragment>
          <Button
            aria-label={t("Close Drawer")}
            icon={<CloseIcon />}
            onClick={onClose}
            size="xs"
            variant="transparent"
          >
            {hideCloseButtonText ? null : t("Close")}
          </Button>
          {!hideBar ? (
            <div className="mr-4 ml-2 self-stretch border-r border-[var(--scraps-theme-border-primary)]" />
          ) : null}
        </Fragment>
      ) : null}
      {children}
    </header>
  );
}

export function DrawerBody({ className, ...props }: HTMLAttributes<HTMLElement>) {
  return <aside className={cn("px-6 py-4 text-sm", className)} {...props} />;
}

export function useDrawerContentContext() {
  return useContext(DrawerContentContext);
}

function DrawerRendererView({
  closeDrawer,
  renderer,
}: {
  closeDrawer: () => void;
  renderer: DrawerRenderer | null;
}) {
  return renderer?.({ closeDrawer }) ?? null;
}

type DrawerErrorBoundaryProps = {
  children: ReactNode;
  onDismiss: () => void;
};

class DrawerErrorBoundary extends Component<DrawerErrorBoundaryProps, { failed: boolean }> {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  render() {
    if (!this.state.failed) return this.props.children;
    return (
      <DrawerBody role="alert">
        <p>{t("There was a problem rendering the drawer.")}</p>
        <Button onClick={this.props.onDismiss}>{t("Close")}</Button>
      </DrawerBody>
    );
  }
}

type GlobalDrawerProps = {
  children?: ReactNode;
  location?: Location;
};

export function GlobalDrawer({ children, location }: GlobalDrawerProps) {
  const [currentDrawerConfig, setCurrentDrawerConfig] = useState<StoredDrawerConfig>();
  const currentDrawerConfigRef = useRef(currentDrawerConfig);
  const panelRef = useRef<HTMLDivElement>(null);
  const lockId = useId();
  const revisionRef = useRef(0);
  const sawInitialLocation = useRef(false);
  const isDrawerOpen = currentDrawerConfig !== undefined;

  const closeDrawer = useCallback(() => {
    bodyScrollLock.release(lockId);
    setCurrentDrawerConfig(undefined);
  }, [lockId]);

  const openDrawer = useCallback<DrawerContextValue["openDrawer"]>(
    (renderer, options, callerId) => {
      if (options.mode !== "passive") {
        bodyScrollLock.acquire(lockId);
      } else {
        bodyScrollLock.release(lockId);
      }
      revisionRef.current += 1;
      setCurrentDrawerConfig({
        renderer,
        options,
        callerId,
        revision: revisionRef.current,
      });
      options.onOpen?.();
    },
    [lockId],
  );

  const handleClose = useCallback(() => {
    currentDrawerConfigRef.current?.options.onClose?.();
    closeDrawer();
  }, [closeDrawer]);

  useEffect(() => {
    currentDrawerConfigRef.current = currentDrawerConfig;
  }, [currentDrawerConfig]);

  useLayoutEffect(() => {
    if (!location) return;
    if (!sawInitialLocation.current) {
      sawInitialLocation.current = true;
      return;
    }

    const current = currentDrawerConfigRef.current;
    if (
      current &&
      (current.options.shouldCloseOnLocationChange?.(location) ??
        current.options.mode !== "passive")
    ) {
      closeDrawer();
    }
  }, [closeDrawer, location]);

  useEffect(() => {
    if (!isDrawerOpen) return;

    const handlePointerDown = (event: PointerEvent) => {
      const current = currentDrawerConfigRef.current;
      const target = event.target;
      if (
        !current ||
        current.options.mode === "passive" ||
        !(target instanceof Element) ||
        panelRef.current?.contains(target)
      ) {
        return;
      }

      const shouldClose = current.options.shouldCloseOnInteractOutside
        ? current.options.shouldCloseOnInteractOutside(target)
        : shouldCloseOnInteractOutsideByDefault(target);
      if (shouldClose) handleClose();
    };

    document.addEventListener("pointerdown", handlePointerDown);
    return () => document.removeEventListener("pointerdown", handlePointerDown);
  }, [handleClose, isDrawerOpen]);

  useHotkeys([
    {
      match: "Escape",
      enabled: isDrawerOpen,
      skipPreventDefault: true,
      callback: (event) => {
        if (document.querySelector("#modal-portal [role='dialog']")) return;
        event.preventDefault();
        handleClose();
      },
    },
  ]);

  useEffect(
    () => () => {
      bodyScrollLock.release(lockId);
    },
    [lockId],
  );

  const current = currentDrawerConfig;
  const mode = current?.options.mode ?? "blocking";

  return (
    <DrawerContext.Provider
      value={{
        activeDrawerId: current?.callerId ?? null,
        closeDrawer,
        openDrawer,
        panelRef,
      }}
    >
      <AnimatePresence>
        {isDrawerOpen && mode !== "passive" ? (
          <Backdrop data-drawer-backdrop="" key="backdrop" zIndex="drawer" />
        ) : null}
        {current ? (
          <DrawerPanel
            ariaLabel={current.options.ariaLabel}
            drawerKey={current.options.drawerKey}
            drawerMaxWidth={current.options.drawerMaxWidth}
            drawerWidth={current.options.drawerWidth}
            mode={mode}
            onClose={handleClose}
            panelForwardRef={panelRef}
            resizable={current.options.resizable}
          >
            <DrawerErrorBoundary key={current.revision} onDismiss={handleClose}>
              <DrawerRendererView closeDrawer={handleClose} renderer={current.renderer} />
            </DrawerErrorBoundary>
          </DrawerPanel>
        ) : null}
      </AnimatePresence>
      {children}
    </DrawerContext.Provider>
  );
}

export function useDrawer() {
  const context = useContext(DrawerContext);
  const callerId = useId();
  const openDrawerRef = useRef(context.openDrawer);

  useEffect(() => {
    openDrawerRef.current = context.openDrawer;
  });

  const openDrawer = useCallback(
    (renderer: DrawerConfig["renderer"], options: DrawerOptions) => {
      openDrawerRef.current(renderer, options, callerId);
    },
    [callerId],
  );

  return {
    openDrawer,
    closeDrawer: context.closeDrawer,
    panelRef: context.panelRef,
    isDrawerOpen: context.activeDrawerId === callerId,
    isAnyDrawerOpen: context.activeDrawerId !== null,
  };
}
